using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
using OcctSharp.Generator.TypeMapping;
namespace OcctSharp.Generator.Tests;
public sealed class TopologyExchangeContractTests {
 static BindingDeclaration Declaration(CopiedCollectionOperationContract.Operation op)=>new(op.StableId,op.NativeName,op.NativeName.Contains("::Interface_EntityIterator",StringComparison.Ordinal)?BindingDeclarationKind.Constructor:BindingDeclarationKind.Method,op.NativeName.Split("::")[0]+".hxx",1,1){NativeSignature=op.Signature,Access=BindingAccess.Public,ProductModule=op.NativeName.StartsWith("BRep",StringComparison.Ordinal)||op.NativeName.StartsWith("ShapeUpgrade",StringComparison.Ordinal)?OcctProductModule.Modeling:OcctProductModule.DataExchange};
 static BindingType Type(string s)=>new(s,s,s,s,[new(BindingTypeLayerKind.Value,false)],null,[],false,null);
 [Fact]public void ExactSignatureDriftPrivateDeletedAndManualCandidatesAreRejected(){var op=TopologyExchangeOperationContract.Operations.Values.First(o=>!o.Supporting);var d=Declaration(op);Assert.True(TopologyExchangeOperationContract.Contains(d));Assert.False(TopologyExchangeOperationContract.Contains(d with{NativeSignature=d.NativeSignature+" "}));Assert.False(TopologyExchangeOperationContract.Contains(d with{Access=BindingAccess.Private}));Assert.False(TopologyExchangeOperationContract.Contains(d with{IsDeleted=true}));Assert.False(TopologyExchangeOperationContract.Contains(d with{SupportState=BindingSupportState.Manual}));}
 [Fact]public void UnsafeCursorCopiesRecursiveGraphAndMutableMapsStayClosed(){Assert.DoesNotContain(TopologyExchangeOperationContract.Operations.Values,o=>o.Signature.Contains("const Interface_EntityIterator &",StringComparison.Ordinal));Assert.DoesNotContain(TopologyExchangeOperationContract.Operations.Values,o=>o.NativeName=="Interface_Graph::TypedSharings");Assert.DoesNotContain(TopologyExchangeOperationContract.Operations.Values,o=>o.NativeName.EndsWith("::Context",StringComparison.Ordinal));}
 [Fact]public void ArbitraryContainerDoesNotBroadenGlobalTypeMap(){var t=Type("NCollection_List<TopoDS_Shape>");var map=InitialTypeMap.FromModel(new BindingModel([]));Assert.False(map.TryMap(t,BindingTypeUsage.Parameter,out _));var d=Declaration(TopologyExchangeOperationContract.Operations.Values.First(o=>o.NativeName=="BRepAlgoAPI_BuilderAlgo::Arguments"));Assert.True(TopologyExchangeOperationContract.TryMap(d,t,BindingTypeUsage.ReturnValue,map,out var p));Assert.Equal("TM015Shape",p!.RuleId);Assert.False(TopologyExchangeOperationContract.TryMap(d with{StableId="unapproved"},t,BindingTypeUsage.ReturnValue,map,out _));}
 [Fact]public void PartialContractCannotPublishAnInflatedMigrationManifest(){var d=Declaration(TopologyExchangeOperationContract.Operations.Values.First());Assert.Throws<InvalidDataException>(()=>TopologyExchangeOperationEmitter.Emit("8.0.1",new BindingModel([d]),[]));}
 [Fact]public void CompleteContractProducesBothOwningModulesDeterministically(){var model=new BindingModel(TopologyExchangeOperationContract.Operations.Values.Select(Declaration));var a=TopologyExchangeOperationEmitter.Emit("8.0.1",model,[]);var b=TopologyExchangeOperationEmitter.Emit("8.0.1",model,[]);Assert.Equal(7,a.Files.Count);Assert.Equal(a.Files.Select(f=>f.Content),b.Files.Select(f=>f.Content));Assert.Equal(TopologyExchangeOperationContract.Operations.Count,a.SourceStableIds.Count);}
}
